SELECT  coalesce(json_agg("root" ORDER BY "root.pg.note" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."note" AS "note"       ) AS "_e"      ) ) AS "root", "_root.base"."note" AS "root.pg.note" FROM  (SELECT  *  FROM "public"."revision"  WHERE (EXISTS  (SELECT  1  FROM "public"."article" AS "__be_0_article" WHERE (((("__be_0_article"."author_id") = ("public"."revision"."author_id")) AND ((("__be_0_article"."id") = ("public"."revision"."article_id")) AND ('true'))) AND (('true') AND (((("__be_0_article"."id") = (('1')::integer)) AND ('true')) AND ('true'))))     ))   ORDER BY "note" ASC NULLS LAST  ) AS "_root.base"    ORDER BY "root.pg.note" ASC NULLS LAST  ) AS "_root"
